// Ablage-Zeilen → Cockpit-Vertrag. Verarbeitet alle gelesenen Zeilen, filtert optional auf objektId.
const anfrage = $('Datenraum-Status abrufen').first().json;
const filterId = anfrage.query?.objektId ?? null;
const zeilen = $input.all().map((i) => i.json).filter((z) => z && (z.objektId || z.objektName));
const objekte = zeilen
  .filter((z) => !filterId || z.objektId === filterId || z.objektName === filterId)
  .map((z) => ({
    objektId: z.objektId ?? null,
    objektName: z.objektName ?? null,
    stand: z.stand ?? null,
    dokumente: Array.isArray(z.dokumente) ? z.dokumente : JSON.parse(z.dokumente ?? '[]'),
    kennwerte: Array.isArray(z.kennwerte) ? z.kennwerte : JSON.parse(z.kennwerte ?? '[]'),
    freigaben: Array.isArray(z.freigaben) ? z.freigaben : JSON.parse(z.freigaben ?? '[]'),
  }));
const stand = objekte.map((o) => o.stand).filter(Boolean).sort().pop() ?? new Date().toISOString();
return [{ json: { stand, anzahl: objekte.length, objekte } }];

// Lauf-Liste der Engine in einzelne Elemente auftrennen.
const roh = $input.first().json;
const laeufe = Array.isArray(roh.laeufe) ? roh.laeufe : [];
if (laeufe.length === 0) return [];
return laeufe.map((lauf) => ({ json: { lauf } }));

// Lauf-Übersicht von Modul 01 auf den Cockpit-Vertrag abbilden.
// Die Engine liefert Prüffälle (eintraege) und Kennzahlen (kpi), keine
// vollständige Dokumentliste. Entsprechend werden nur Prüffälle als
// Dokumente gemeldet; die Mengen stehen in den Kennwerten.
const jetzt = new Date().toISOString();
const OBJEKTART = { mehrfamilienhaus: 'Mehrfamilienhaus', wohn_und_geschaeftshaus: 'Wohn- und Geschäftshaus', wohnanlage: 'Wohnanlage', grundstueck: 'Grundstück', ausnahme: 'Ausnahme' };
const de = (n, nk) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: nk });
function kennwerteAusEngine(k) {
  if (!k || typeof k !== 'object') return [];
  const aus = [];
  if (k.strasse?.sicher || k.ort?.sicher) {
    const teile = [k.strasse?.wert, [k.plz?.wert, k.ort?.wert].filter(Boolean).join(' ')].filter(Boolean);
    aus.push({ feld: 'Objektadresse', wert: teile.join(', '), quelle: 'Modul 01 (aus ' + (k.dokumenteMitHinweis ?? 0) + ' Dokumenten)', pruefstatus: (k.strasse?.sicher && k.ort?.sicher) ? 'uebernommen' : 'pruefen' });
  }
  const v = k.vorschlaege ?? {};
  const eintrag = (feld, wert, s) => aus.push({ feld, wert, quelle: 'Modul 01 · Vorschlag (' + s.stimmen + '/' + s.nennungen + ', ' + (s.quellen ?? []).join(', ') + ')', pruefstatus: 'pruefen' });
  if (v.objektart) eintrag('Assetklasse (Vorschlag)', OBJEKTART[v.objektart.wert] ?? String(v.objektart.wert), v.objektart);
  if (v.einheiten) eintrag('Einheiten (Vorschlag)', String(v.einheiten.wert), v.einheiten);
  if (v.wohnflaeche_qm) eintrag('Fläche (Vorschlag)', de(v.wohnflaeche_qm.wert, 1) + ' m²', v.wohnflaeche_qm);
  if (v.jahresnettokaltmiete_eur) eintrag('Jahresnettokaltmiete (Vorschlag)', de(v.jahresnettokaltmiete_eur.wert, 0) + ' EUR', v.jahresnettokaltmiete_eur);
  // Pre-Sound-Fakten (Lucas Vorlage, 03.11.2026) — ebenfalls nur Vorschläge
  if (v.baujahr) eintrag('Baujahr (Vorschlag)', String(v.baujahr.wert), v.baujahr);
  if (v.grundstuecksflaeche_qm) eintrag('Grundstücksfläche (Vorschlag)', de(v.grundstuecksflaeche_qm.wert, 1) + ' m²', v.grundstuecksflaeche_qm);
  if (v.flurstuecke) eintrag('Flurstücke (Vorschlag)', String(v.flurstuecke.wert), v.flurstuecke);
  if (v.wohneinheiten || v.gewerbeeinheiten || v.stellplaetze) {
    const teile = [v.wohneinheiten ? v.wohneinheiten.wert + ' WE' : null, v.gewerbeeinheiten ? v.gewerbeeinheiten.wert + ' GE' : null, v.stellplaetze ? v.stellplaetze.wert + ' Stellplätze' : null].filter(Boolean);
    eintrag('Einheiten WE | GE (Vorschlag)', teile.join(' | '), v.wohneinheiten ?? v.gewerbeeinheiten ?? v.stellplaetze);
  }
  if (v.leerstand_prozent) eintrag('Leerstand (Vorschlag)', de(v.leerstand_prozent.wert, 1) + ' %', v.leerstand_prozent);
  if (v.jnkm_soll_eur) eintrag('JNKM SOLL (Vorschlag)', de(v.jnkm_soll_eur.wert, 0) + ' EUR', v.jnkm_soll_eur);
  return aus;
}
return $input.all().map((i) => {
  const u = i.json ?? {};
  const eintraege = Array.isArray(u.eintraege) ? u.eintraege : [];
  const dokumente = eintraege.map((e) => ({
    name: e.anzeige ?? e.datei ?? 'unbenannt',
    status: e.art === 'review' ? 'in_pruefung' : 'unklar',
  }));
  const k = u.kpi ?? null;
  const q = u.qualitaet ?? null;
  const g = u.gedaechtnis ?? null;
  const prozent = (a) => Math.round(Number(a ?? 0) * 100) + ' %';
  const kennwerte = k === null ? [] : [
    { feld: 'verarbeitet', wert: String(k.verarbeitet ?? 0), quelle: 'Modul 01' },
    { feld: 'abgelegt', wert: String(k.abgelegt ?? 0), quelle: 'Modul 01' },
    { feld: 'zu bestätigen', wert: String(k.qc ?? 0), quelle: 'Modul 01' },
    { feld: 'in Prüfung', wert: String(k.review ?? 0), quelle: 'Modul 01' },
    { feld: 'Duplikate', wert: String(k.duplikate ?? 0), quelle: 'Modul 01' },
    { feld: 'offen', wert: String(k.offen ?? 0), quelle: 'Modul 01', pruefstatus: 'pruefen' },
    // Objekt-Kennwerte aus den Dokumenten (02.11.2026): Adresse nur wenn „sicher“,
    // Assetklasse (SEILs 5 Klassen) und Key Facts IMMER als Vorschlag zum Prüfen
    ...kennwerteAusEngine(u.kennwerte ?? null),
    // Abnahme A4 (02.11.2026): die drei Kennzahlen je Lauf aus dem Datenraum-Center
    ...(q === null ? [] : [
      { feld: 'automatisch abgelegt', wert: prozent(q.anteil_automatisch), quelle: 'Modul 01' },
      { feld: 'von Menschen geprüft', wert: prozent(q.anteil_geprueft), quelle: 'Modul 01' },
      { feld: 'nachträglich korrigiert', wert: prozent(q.anteil_korrigiert), quelle: 'Modul 01' },
      { feld: 'Konfidenz-Schwelle', wert: prozent(q.schwelle), quelle: 'Modul 01' },
    ]),
    // Abnahme A10 (03.11.2026): Gedächtnis — wiedererkannte Dateien je Lauf und
    // Trefferquote über alle Läufe (bestätigt ohne Korrektur / alle Bestätigungen)
    ...(g === null ? [] : [
      { feld: 'Gedächtnis: wiedererkannt', wert: g.treffer + ' von ' + g.gefragt, quelle: 'Modul 01' },
      { feld: 'Gedächtnis: ohne Prüfung abgelegt', wert: String(g.angehoben ?? 0), quelle: 'Modul 01' },
      { feld: 'Gedächtnis: Widersprüche', wert: String(g.widerspruch ?? 0), quelle: 'Modul 01', ...(g.widerspruch > 0 ? { pruefstatus: 'pruefen' } : {}) },
      ...(g.gesamt && g.gesamt.trefferquote !== null ? [{ feld: 'Gedächtnis: Trefferquote', wert: prozent(g.gesamt.trefferquote), quelle: 'Modul 01 (alle Läufe)' }] : []),
    ]),
  ];
  return { json: { objektId: null, objektName: u.lauf ?? null, stand: jetzt,
                   dokumente, kennwerte, freigaben: [] } };
});
